$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$modulePath = Join-Path $pkg "ahos\openhands_worker_adapter.py"
$testPath = Join-Path $pkg "tests\test_openhands_worker_adapter.py"
$backlogPath = Join-Path $pkg "AHOS_BACKLOG.json"
$python = Join-Path $root ".venv\Scripts\python.exe"

if (-not (Test-Path $backlogPath)) { throw "AHOS_BACKLOG.json not found." }
if (-not (Test-Path $python)) { throw "Python venv not found." }

[IO.File]::WriteAllBytes($modulePath, [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($testPath, [Convert]::FromBase64String(""))

$b = Get-Content $backlogPath -Raw | ConvertFrom-Json
if (-not ($b.tasks | Where-Object { $_.id -eq "AHOS-026" })) {
    $b.tasks += [pscustomobject]@{
        id = "AHOS-026"
        title = "Add OpenHands execution bridge for virtual software workers"
        status = "pending"
        risk = "low"
        authority = "B"
        requires_owner_approval = $false
        task = "Add a zero-cost tested adapter that converts AHOS WorkItems into isolated OpenHands-style builder executions and maps builder results back into the virtual-worker runtime. Keep the real builder injected, preserve approval gates, and make no live AI calls in this task."
    }
    [IO.File]::WriteAllText(
        $backlogPath,
        ($b | ConvertTo-Json -Depth 12),
        (New-Object System.Text.UTF8Encoding($false))
    )
}

Write-Host "=== AHOS-026 OPENHANDS WORKER BRIDGE ==="
Write-Host "Building the bridge only. NO live AI call will be made."
Write-Host "Running full AHOS tests locally..."

$oldPythonPath = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg
    & $python -m pytest -q
    $testExit = $LASTEXITCODE
} finally {
    Pop-Location
    $env:PYTHONPATH = $oldPythonPath
}
if ($testExit -ne 0) { throw "AHOS-026 tests failed." }

$b = Get-Content $backlogPath -Raw | ConvertFrom-Json
$t = $b.tasks | Where-Object { $_.id -eq "AHOS-026" } | Select-Object -First 1
$t.status = "completed"
if ($t.PSObject.Properties.Name -contains "completed_at") {
    $t.completed_at = [DateTime]::UtcNow.ToString("o")
} else {
    $t | Add-Member -NotePropertyName completed_at -NotePropertyValue ([DateTime]::UtcNow.ToString("o"))
}
[IO.File]::WriteAllText(
    $backlogPath,
    ($b | ConvertTo-Json -Depth 12),
    (New-Object System.Text.UTF8Encoding($false))
)

git -C $ws add ahos_core/ahos/openhands_worker_adapter.py ahos_core/tests/test_openhands_worker_adapter.py ahos_core/AHOS_BACKLOG.json
git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" commit -m "feat(ahos): add OpenHands virtual worker bridge"
if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

git -C $ws push origin HEAD
if ($LASTEXITCODE -ne 0) { throw "git push failed." }

Write-Host ""
Write-Host "=== AHOS-026 COMPLETE ==="
Write-Host "Full AHOS tests: PASS"
Write-Host "Backlog: AHOS-026 -> completed"
Write-Host "Git push: PASS"
Write-Host "OpenHands bridge: READY"
Write-Host "Live AI calls: 0"
Write-Host "Paid API spend: USD 0"
Write-Host "Next step requires explicit approval before one real AI worker smoke test."
